  'Creator Studio content management uses the same visibility model: public, unlisted, or private. Scheduled videos use requested visibility after release.' => 'Isakoso akoonu Studio Ẹlẹda nlo awoṣe hihan kanna: ti gbogbo eniyan, aisi atokọ, tabi ikọkọ. Awọn fidio ti a ṣe eto lo hihan ti o beere lẹhin itusilẹ.',
