  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Ilọsiwaju ṣiṣiṣẹsẹhin, ipo atẹle, awọn ayanfẹ, awọn asọye, ṣiṣe alabapin, awọn iwifunni, ati awọn atupale alabojuto ti wa ni ipamọ sinu ibi ipamọ data nigbati o sopọ mọ awọn ẹya ipilẹ ti o jẹri.',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Sisisẹsẹhin, awọn asọye, awọn ayanfẹ, wo nigbamii, ṣiṣe alabapin, awọn iwifunni, awọn ifiranṣẹ, awọn akojọ orin, ati awọn eto ede wa nipasẹ lilọ kiri akọkọ ati akojọ akọọlẹ.',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub jẹ ipilẹ fidio kan fun ikojọpọ, wiwo, ṣiṣe eto, iṣakoso, ati ṣiṣatunṣe akoonu olupilẹṣẹ lati akọọlẹ kan.',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub jẹ ipilẹ fidio ti n ṣiṣẹ lori imuṣiṣẹ yii, ti a ṣe fun awọn olupilẹṣẹ, awọn oluwo, awọn agbegbe, ati awọn oniṣẹ ẹrọ.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub n pese awọn ikanni olupilẹṣẹ, awọn gbigbe fidio, titẹjade iṣeto, ṣiṣe alabapin, awọn asọye, awọn atokọ orin, wo nigbamii, awọn oju-iwe akoonu laaye, ati awọn irinṣẹ iṣakoso lati ori pẹpẹ kan.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub nlo awọn kuki pataki ati ibi ipamọ ẹrọ aṣawakiri fun awọn akoko iwọle, ijẹrisi API, CSRF/ ihuwasi aabo, yiyan ede, yiyan akori, ipo akojo akoto, ati awọn ẹya miiran ti o nilo fun ohun elo lati ṣiṣẹ.',
