  'Short summary' => 'Akopọ kukuru',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Wọle ki o lo Eto fun akọọlẹ, profaili, ọrọ igbaniwọle, iwifunni, asiri, ati awọn ayanfẹ Eleda. Gbigbe Ẹlẹda ati awọn ọran akoonu yẹ ki o pẹlu akọle fidio, ikanni, ẹrọ aṣawakiri, ati eyikeyi aṣiṣe sisẹ ti o han lori oju-iwe ikojọpọ.',
  'Sign in for account support' => 'Wọle fun atilẹyin akọọlẹ',
