  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Awọn akọsilẹ imọ-ẹrọ fun awọn iṣọpọ pẹlu PlayHub API lọwọlọwọ ati ikojọpọ ṣiṣan iṣẹ.',
  'Tell us more about your question or request...' => 'Sọ fun wa diẹ sii nipa ibeere tabi ibeere rẹ...',
  'Terms of Use' => 'Awọn ofin lilo',
  'The configured' => 'Awọn tunto',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Oju-iwe olupilẹṣẹ naa ni asopọ si igbehin Laravel laaye: atokọ ipa-ọna, awọn iṣiro data data, awọn opin gbigbe, ati awọn metadata pẹpẹ jẹ ti kojọpọ lati /api/awọn olupilẹṣẹ.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Iwaju awọn ile itaja awọn ayanfẹ bii ede ti a yan, akori, isinyi ṣiṣiṣẹsẹhin, iṣọwo ilọsiwaju, ati ipo wiwo nitori iriri naa wa ni ibamu jakejado lilọ kiri oju-iwe ati awọn atunbere.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Iṣẹ ṣiṣatunṣe ṣe koodu awọn iyipada, ṣẹda awọn eekanna atanpako nigbati o nilo, tọju awọn akọle, ati samisi awọn fidio ti o ṣetan nigbati ṣiṣe ba pari. Awọn fidio eto ọjọ iwaju wa ni ikọkọ titi ti oluṣeto yoo fi tu wọn silẹ.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Eto ikojọpọ jẹ atilẹyin data data, ṣe atilẹyin awọn ẹka ati awọn ede lati API, ṣiṣe awọn fidio ti a gbejade, tọju awọn eekanna atanpako ati awọn akọle, ati tọju akoonu iṣeto ni ikọkọ titi di akoko idasilẹ rẹ.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Oju-iwe yii ṣe alaye bi PlayHub ṣe nlo awọn kuki ati ibi ipamọ ẹrọ aṣawakiri fun awọn akoko, aabo, awọn ayanfẹ, ṣiṣiṣẹsẹhin, ati awọn ẹya ti o jẹri.',
