  'Upload pipeline' => 'Po si opo gigun ti epo',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Ṣe agbejade, wo, ṣe alabapin, iwọntunwọnsi, ati kọ pẹlu data PlayHub laaye.',
  'Uploaded videos' => 'Awọn fidio ti a kojọpọ',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Awọn fidio ti a kojọpọ ti wa ni koodu sinu awọn atunwi ti o ṣee mu ṣiṣẹ. Akoko ṣiṣe da lori iwọn faili, iye akoko, fifuye olupin, ati ipo isinyi. Oju-iwe ikojọpọ ati Studio Studio ṣe afihan ipo ṣiṣe gidi lati igbasilẹ fidio.',
  'Uploads, scheduling, and processing are available.' => 'Àwọn ìrùsókè, ìtòlẹ́sẹẹsẹ, àti sísọ̀rọ̀ wà.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Lo /api/awọn fidio, awọn aaye ipari ikanni, ati awọn ipa-ọna ti o jẹri fun awọn ṣiṣan iṣẹ ẹlẹda.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Lo awọn iṣe ijabọ ti a ṣe sinu fun awọn fidio ati awọn asọye nitorinaa awọn alabojuto gba itọkasi akoonu gangan. Awọn oju-iwe dasibodu alabojuto lo data data laaye fun awọn olumulo, akoonu, awọn ijabọ, owo-iworo, awọn atupale, atilẹyin, awọn ipa, ati awọn eto eto.',
  'Use Contact Us' => 'Lo Kan si Wa',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Lo JSON fun awọn ibeere API deede ati FormData fun awọn ikojọpọ faili. Maṣe fori afọwọsi: awọn ẹka ati awọn ede jẹ ID data data, hihan ni opin si gbogbo eniyan, ti a ko ṣe atokọ, tabi ikọkọ, ati awọn akọle gba SRT, VTT, tabi awọn faili TXT.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Lo Eto lati ṣe imudojuiwọn profaili rẹ, aabo, ọrọ igbaniwọle, ifijiṣẹ ifosiwewe meji, awọn ẹrọ, awọn ayanfẹ, ati awọn aṣayan iwifunni. Ti o ko ba le wọle si akọọlẹ rẹ, lo sisan iwọle ki o pese imeeli akọọlẹ si alabojuto aaye naa.',
  'Use the contact form' => 'Lo fọọmu olubasọrọ',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Lo awọn iṣe ijabọ lori awọn fidio, awọn asọye, ati awọn ifiweranṣẹ agbegbe ki awọn alabojuto gba itọkasi akoonu gangan.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Lo awọn iṣe ijabọ lori awọn fidio, awọn asọye, ati awọn ifiweranṣẹ agbegbe nigbati akoonu le rú awọn ofin pẹpẹ. Awọn ijabọ wọnyi ni a so si igbasilẹ akoonu gidi ati pe o dara ju ifiranṣẹ jeneriki lọ nitori awọn alabojuto le ṣe atunyẹwo ohun kan gangan.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Lo ikanni PlayHub ti o tọ fun iranlọwọ akọọlẹ, awọn ijabọ akoonu, awọn ọran imọ-ẹrọ, ati awọn ibeere alabojuto.',
  'Video categories' => 'Video isori',
  'Video for everyone. Built for creators and viewers.' => 'Fidio fun gbogbo eniyan. Itumọ ti lati gidi Syeed data.',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Gbigbe fidio, ṣiṣe iṣeto, awọn eekanna atanpako, ati awọn ọran ṣiṣe.',
  'Videos, thumbnails, captions, processing.' => 'Awọn fidio, awọn eekanna atanpako, awọn akọle, ṣiṣe.',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Awọn oluwo le lọ kiri awọn ẹka, wa awọn fidio, wo akoonu, ṣe alabapin si awọn ikanni, fi awọn fidio pamọ lati wo nigbamii, asọye, gba awọn iwifunni, ati ṣakoso ede ati awọn ayanfẹ iraye si.',
  'Viewing and community help' => 'Wiwo ati iranlọwọ agbegbe',
  'Waiting for backend endpoint inventory.' => 'Nduro fun akojo oja ẹhin ipari.',
  'We’re here to help.' => 'A wa nibi lati ṣe iranlọwọ.',
  'What is PlayHub?' => 'Kini PlayHub?',
  'What PlayHub does' => 'Kini PlayHub ṣe',
  'Where do contact messages go?' => 'Nibo ni awọn ifiranṣẹ olubasọrọ lọ?',
  'Why is my video still processing?' => 'Kini idi ti fidio mi ṣi n ṣiṣẹ?',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Bẹẹni. Lo ọjọ iṣeto abinibi ati aaye akoko lori oju-iwe ikojọpọ. Awọn ile itaja backend_at, ṣe ilana fidio, tọju rẹ ni ikọkọ lakoko ti ọjọ wa ni ọjọ iwaju, ati tu silẹ nigbati oluṣeto Laravel ba ṣiṣẹ lẹhin akoko ti a ṣeto.',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Bẹẹni. Lo aaye iṣeto abinibi lori Ikojọpọ. Awọn ile itaja afẹyinti ti iṣeto_at ati tu fidio naa jade lẹhin ṣiṣe nigbati akoko iṣeto ba ti de.',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'O nlo kiri bi alejo. Wọle lati wọle si awọn irinṣẹ-ipamọ kan pato.',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'O ni iduro fun awọn iwe-ẹri akọọlẹ rẹ, iṣẹ profaili, akoonu ti o gbejade, awọn asọye, awọn ifiranṣẹ, ati eyikeyi olupilẹṣẹ tabi awọn iṣe alabojuto ti a ṣe lati akọọlẹ rẹ. Lo awọn ọrọ igbaniwọle to lagbara ati tọju awọn ọna ifijiṣẹ ifosiwewe meji lọwọlọwọ.',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'O le ko awọn kuki aṣawakiri kuro ati ibi ipamọ agbegbe ni awọn eto aṣawakiri rẹ. Pipade ibi ipamọ to ṣe pataki le fi orukọ silẹ, tun awọn ayanfẹ ede/akori to fẹ, yọ ipo ṣiṣiṣẹsẹhin agbegbe kuro, ati nilo ki o wọle lẹẹkansii.',
  'You receive a response by email.' => 'O gba esi nipasẹ imeeli.',
  'You’re in control' => 'O wa ni iṣakoso',
  'Your choices' => 'Awọn yiyan rẹ',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Ifiranṣẹ rẹ ti wa ni fipamọ taara ni ẹhin oju opo wẹẹbu ati han ninu dasibodu abojuto labẹ Atilẹyin.',
